import{_ as t,c as a,o as i,ah as l}from"./chunks/framework.DaDXF32t.js";const m=JSON.parse('{"title":"C++ TUI Installer Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-08-02-cpp-tui-installer.md","filePath":"superpowers/plans/2026-08-02-cpp-tui-installer.md","lastUpdated":1785749755000}'),o={name:"superpowers/plans/2026-08-02-cpp-tui-installer.md"};function r(n,e,s,c,d,p){return i(),a("div",null,e[0]||(e[0]=[l('<h1 id="c-tui-installer-implementation-plan" tabindex="-1">C++ TUI Installer Implementation Plan <a class="header-anchor" href="#c-tui-installer-implementation-plan" aria-label="Permalink to “C++ TUI Installer Implementation Plan”">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> Build a cross-platform C++ TUI installer that migrates legacy BAAS installs, manages main and OCR repositories transactionally, and keeps a uv-based portable runtime inside the installation directory.</p><p><strong>Architecture:</strong> A standalone CMake/vcpkg application under <code>deploy/installer</code> owns executable-relative paths, TOML migration, ranked source fallback, Git CLI/libgit2 operations, MirrorChyan, parallel preparation, main-then-OCR deployment, uv setup, TUI rendering, and launch. Repository SHAs are persisted only after deployment and dependency synchronization succeed.</p><p><strong>Tech Stack:</strong> C++20, CMake, vcpkg, FTXUI, libcurl, libgit2, toml++, nlohmann/json, libarchive, OpenSSL, Catch2, GitHub Actions.</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to “Global Constraints”">​</a></h2><ul><li>Base: <code>upstream/master</code>; branch: <code>feat/cpp-tui-installer</code>.</li><li>Only executable-adjacent <code>setup.toml</code>; never create <code>config.toml</code>.</li><li>Preserve/synchronize legacy and current setup schemas and unknown fields.</li><li><code>runtime_path = &quot;default&quot;</code> means portable; all uv, Python, cache, temp, and state paths stay below the install root.</li><li>Exclude <code>MAIN_REPO_SRC_DEV</code> and <code>baas-cdn.kiramei.workers.dev</code>.</li><li>Main uses MirrorChyan when selected; otherwise each ranked URL uses Git CLI then libgit2. OCR always uses Git.</li><li>Prepare main/OCR concurrently; deploy main first, then OCR to <code>core/ocr/baas_ocr_client/bin</code>.</li><li>Publish four executables and SHA256SUMS to GitHub Releases for <code>v*</code> tags.</li><li>Tests focus on migration, fallback, deployment/rollback, and portability.</li></ul><hr><h3 id="task-1-cmake-application-skeleton-and-portable-paths" tabindex="-1">Task 1: CMake application skeleton and portable paths <a class="header-anchor" href="#task-1-cmake-application-skeleton-and-portable-paths" aria-label="Permalink to “Task 1: CMake application skeleton and portable paths”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/CMakeLists.txt</code></li><li>Create: <code>deploy/installer/vcpkg.json</code></li><li>Create: <code>deploy/installer/include/baas_installer/paths.hpp</code></li><li>Create: <code>deploy/installer/src/paths.cpp</code></li><li>Create: <code>deploy/installer/src/main.cpp</code></li><li>Create: <code>deploy/installer/tests/test_paths.cpp</code></li><li>Modify: <code>deploy/installer/README.md</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Produces <code>InstallPaths::from_executable(path)</code> with <code>root</code>, <code>setup_toml</code>, <code>tmp_dir</code>, <code>toolkit_dir</code>, <code>uv_dir</code>, <code>venv_dir</code>, <code>logs_dir</code>, and <code>state_dir</code>.</p></li><li><p>Produces <code>BlueArchiveAutoScript</code> and <code>baas-installer-tests</code> targets.</p></li><li><p>[ ] Write a failing Catch2 test using <code>E:\\\\tmp\\\\BAAS\\\\BlueArchiveAutoScript.exe</code> and assert every path is rooted at <code>E:\\\\tmp\\\\BAAS</code>.</p></li><li><p>[ ] Run <code>cmake --preset installer-debug &amp;&amp; cmake --build --preset installer-debug &amp;&amp; ctest --test-dir build/installer-debug -R paths --output-on-failure</code>; expect failure because targets are absent.</p></li><li><p>[ ] Add C++20 CMake/vcpkg manifests and the minimal <code>InstallPaths</code> implementation based on the executable parent, never cwd.</p></li><li><p>[ ] Re-run the focused test and a release build; expect PASS and one executable.</p></li><li><p>[ ] Commit: <code>feat(installer): add C++ build skeleton</code>.</p></li></ul><h3 id="task-2-setup-toml-compatibility-and-atomic-save" tabindex="-1">Task 2: setup.toml compatibility and atomic save <a class="header-anchor" href="#task-2-setup-toml-compatibility-and-atomic-save" aria-label="Permalink to “Task 2: setup.toml compatibility and atomic save”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/config.hpp</code></li><li>Create: <code>deploy/installer/src/config.cpp</code></li><li>Create: <code>deploy/installer/tests/test_config.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>InstallerConfig load_config(const InstallPaths&amp;)</code></p></li><li><p><code>InstallerConfig parse_config(std::string_view)</code></p></li><li><p><code>std::string render_config(const InstallerConfig&amp;)</code></p></li><li><p><code>void save_config_atomic(const InstallerConfig&amp;, const InstallPaths&amp;)</code></p></li><li><p>[ ] Write a failing test with legacy <code>[General]/[URLs]/[Paths]</code>, old SHA aliases, <code>runtime_path = &quot;default&quot;</code>, and a custom table; assert current/legacy output and unknown-field preservation.</p></li><li><p>[ ] Run <code>ctest --test-dir build/installer-debug -R config --output-on-failure</code>; expect missing API failure.</p></li><li><p>[ ] Implement lowercase-first precedence, legacy aliases, defaults, portable <code>&quot;.&quot;</code> paths, <code>package_manager = &quot;uv&quot;</code>, and preserved TOML tree.</p></li><li><p>[ ] Implement sibling <code>.new</code> write, flush, backup, atomic rename, and recovery on failure.</p></li><li><p>[ ] Re-run config tests; expect PASS for mixed schema, unknown fields, and atomic save.</p></li><li><p>[ ] Commit: <code>feat(installer): migrate legacy setup configuration</code>.</p></li></ul><h3 id="task-3-source-constants-ranking-and-http-fallback" tabindex="-1">Task 3: Source constants, ranking, and HTTP fallback <a class="header-anchor" href="#task-3-source-constants-ranking-and-http-fallback" aria-label="Permalink to “Task 3: Source constants, ranking, and HTTP fallback”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/sources.hpp</code></li><li>Create: <code>deploy/installer/src/sources.cpp</code></li><li>Create: <code>deploy/installer/tests/test_sources.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>enum class SourceKind { MainGit, OcrGit, Uv, Cpython, Pypi }</code></p></li><li><p><code>default_sources(kind, config)</code></p></li><li><p><code>load_or_rank_sources(kind, paths, config, probe)</code></p></li><li><p><code>SourceRanking::active_urls()</code> and <code>mark_failed(url)</code></p></li><li><p>[ ] Write a failing test proving the retired custom CDN and dev repo are absent, Gitee can outrank GitHub by measured latency, and a failed URL is demoted.</p></li><li><p>[ ] Run the focused source test; expect missing API failure.</p></li><li><p>[ ] Add approved main/OCR/uv/CPython/PyPI URLs, 5-second HEAD then range-GET probing, and JSON rankings under <code>.baas-installer/source-ranking</code>.</p></li><li><p>[ ] Invalidate rankings when URL sets change and stop after three all-failed ranking cycles.</p></li><li><p>[ ] Re-run source tests; expect PASS.</p></li><li><p>[ ] Commit: <code>feat(installer): add ranked source fallback</code>.</p></li></ul><h3 id="task-4-git-cli-then-libgit2-preparation" tabindex="-1">Task 4: Git CLI then libgit2 preparation <a class="header-anchor" href="#task-4-git-cli-then-libgit2-preparation" aria-label="Permalink to “Task 4: Git CLI then libgit2 preparation”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/git_repository.hpp</code></li><li>Create: <code>deploy/installer/src/git_repository.cpp</code></li><li>Create: <code>deploy/installer/tests/test_git_repository.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>PreparedRepository prepare_repository(const RepositoryRequest&amp;, GitExecutor&amp;, SourceRanking&amp;)</code></p></li><li><p><code>GitExecutor</code> exposes CLI/libgit2 prepare, head, commit, and rollback.</p></li><li><p><code>PreparedRepository</code> records staging/target paths, old/new SHA, URL, backend, and replacement requirement.</p></li><li><p>[ ] Write a failing fake-executor test asserting call order <code>cli:first-url, git2:first-url</code> before advancing URLs.</p></li><li><p>[ ] Run focused test; expect missing API failure.</p></li><li><p>[ ] Implement noninteractive shallow CLI clone/fetch and matching libgit2 operations with bounded timeouts.</p></li><li><p>[ ] Detect invalid <code>.git</code>; prepare a clean staged replacement while preserving protected user paths.</p></li><li><p>[ ] Re-run tests for fallback order, invalid metadata, and noninteractive environment; expect PASS.</p></li><li><p>[ ] Commit: <code>feat(installer): prepare repositories with Git fallback</code>.</p></li></ul><h3 id="task-5-mirrorchyan-staging-and-integrity" tabindex="-1">Task 5: MirrorChyan staging and integrity <a class="header-anchor" href="#task-5-mirrorchyan-staging-and-integrity" aria-label="Permalink to “Task 5: MirrorChyan staging and integrity”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/mirrorchyan.hpp</code></li><li>Create: <code>deploy/installer/src/mirrorchyan.cpp</code></li><li>Create: <code>deploy/installer/tests/test_mirrorchyan.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>validate_cdk(cdk, http)</code></p></li><li><p><code>query_mirror_latest(cdk, current_sha, http)</code></p></li><li><p><code>prepare_mirror_package(latest, paths, http)</code></p></li><li><p><code>apply_mirror_package(package, journal)</code> / <code>rollback_mirror_package(journal)</code></p></li><li><p>[ ] Write a failing test that rejects a bad SHA-256 before any live file changes.</p></li><li><p>[ ] Run focused test; expect missing API failure.</p></li><li><p>[ ] Implement MirrorChyan status mapping, redacted CDK handling, timeouts, streamed download, digest verification, archive extraction, and change journal.</p></li><li><p>[ ] Re-run tests for CDK states, digest rejection, and no pre-verification writes; expect PASS.</p></li><li><p>[ ] Commit: <code>feat(installer): stage MirrorChyan main updates</code>.</p></li></ul><h3 id="task-6-parallel-prepare-and-transactional-ordered-deployment" tabindex="-1">Task 6: Parallel prepare and transactional ordered deployment <a class="header-anchor" href="#task-6-parallel-prepare-and-transactional-ordered-deployment" aria-label="Permalink to “Task 6: Parallel prepare and transactional ordered deployment”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/deployment.hpp</code></li><li>Create: <code>deploy/installer/src/deployment.cpp</code></li><li>Create: <code>deploy/installer/tests/test_deployment.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>WorkflowResult install_or_update(config, paths, services, progress)</code></p></li><li><p><code>commit_prepared(main, ocr, journal)</code></p></li><li><p><code>rollback(journal)</code></p></li><li><p>[ ] Write a failing fake-services test asserting both prepares finish, then <code>commit-main</code>, <code>commit-ocr</code>; on OCR failure assert <code>rollback-ocr</code>, <code>rollback-main</code>, and unchanged SHAs.</p></li><li><p>[ ] Run focused test; expect missing coordinator failure.</p></li><li><p>[ ] Implement UUID staging under <code>tmp/installer</code>, concurrent main/OCR preparation, barrier, main-first/OCR-second placement, required-file validation, JSON journal, and reverse rollback.</p></li><li><p>[ ] Protect installer executable, <code>setup.toml</code>, logs, and user configuration during corrupt-repository replacement.</p></li><li><p>[ ] Re-run deployment tests; expect PASS.</p></li><li><p>[ ] Commit: <code>feat(installer): deploy main and OCR transactionally</code>.</p></li></ul><h3 id="task-7-fully-portable-uv-python-environment" tabindex="-1">Task 7: Fully portable uv/Python environment <a class="header-anchor" href="#task-7-fully-portable-uv-python-environment" aria-label="Permalink to “Task 7: Fully portable uv/Python environment”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/uv_environment.hpp</code></li><li>Create: <code>deploy/installer/src/uv_environment.cpp</code></li><li>Create: <code>deploy/installer/tests/test_uv_environment.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>UvEnvironment make_uv_environment(paths, config)</code></p></li><li><p>Process specs for uv download, <code>python install</code>, relocatable <code>venv</code>, <code>pip compile</code>, <code>pip sync</code>, and cache cleanup.</p></li><li><p><code>requirements_unchanged(...)</code></p></li><li><p>[ ] Write a failing test asserting every UV/XDG/TMP value begins with the simulated moved root and flags include <code>UV_VENV_RELOCATABLE=1</code>, <code>UV_NO_CONFIG=1</code>, and <code>UV_PYTHON_INSTALL_REGISTRY=0</code>.</p></li><li><p>[ ] Run focused test; expect missing API failure.</p></li><li><p>[ ] Implement platform uv archives and all approved scoped directories under <code>toolkit/uv</code>, <code>.venv</code>, and <code>tmp/uv</code>.</p></li><li><p>[ ] Add Python 3.9 install, requirements discovery, compile/sync, and SHA-256 cache; custom runtime bypasses managed setup.</p></li><li><p>[ ] Re-run tests for portable paths, cache hit/miss, and custom-runtime skip; expect PASS.</p></li><li><p>[ ] Commit: <code>feat(installer): manage portable uv runtime</code>.</p></li></ul><h3 id="task-8-ftxui-launcher-logging-and-ocr-handoff" tabindex="-1">Task 8: FTXUI, launcher, logging, and OCR handoff <a class="header-anchor" href="#task-8-ftxui-launcher-logging-and-ocr-handoff" aria-label="Permalink to “Task 8: FTXUI, launcher, logging, and OCR handoff”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/tui.hpp</code></li><li>Create: <code>deploy/installer/src/tui.cpp</code></li><li>Create: <code>deploy/installer/src/launcher.cpp</code></li><li>Modify: <code>deploy/installer/src/main.cpp</code></li><li>Modify: <code>core/ocr/baas_ocr_client/server_installer.py</code></li><li>Modify: <code>main.py</code></li><li>Create: <code>tests/core/ocr/test_server_installer_marker.py</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>run_tui(paths, services)</code></p></li><li><p><code>ProgressSink::task(id, state, detail)</code></p></li><li><p><code>launch_baas(paths, config)</code></p></li><li><p>Python <code>should_skip_installer_managed_update() -&gt; bool</code></p></li><li><p>[ ] Write a failing Python test that creates <code>bin/.baas-installer-managed.json</code> and expects legacy OCR network update to be skipped.</p></li><li><p>[ ] Run <code>pytest tests/core/ocr/test_server_installer_marker.py -q</code>; expect missing function failure.</p></li><li><p>[ ] Implement first-run MirrorChyan choice, masked CDK, progress/waiting rows, retry/Git/exit, safe cancellation, root-local redacted logs, and root-relative launch.</p></li><li><p>[ ] Write the OCR marker only after verified placement; make Python skip only when the marker is valid.</p></li><li><p>[ ] Run Python and CTest suites plus <code>BlueArchiveAutoScript --help</code>; expect PASS and no user-directory files.</p></li><li><p>[ ] Commit: <code>feat(installer): add TUI workflow and OCR handoff</code>.</p></li></ul><h3 id="task-9-four-platform-actions-builds-and-github-releases" tabindex="-1">Task 9: Four-platform Actions builds and GitHub Releases <a class="header-anchor" href="#task-9-four-platform-actions-builds-and-github-releases" aria-label="Permalink to “Task 9: Four-platform Actions builds and GitHub Releases”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>.github/workflows/installer-release.yml</code></li><li>Modify: <code>deploy/installer/README.md</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Matrix: Windows x86_64, Linux x86_64, macOS x86_64, macOS arm64.</p></li><li><p>Triggers: installer-related pull requests, <code>workflow_dispatch</code>, and <code>v*</code> tags.</p></li><li><p>Assets: four named executables plus <code>SHA256SUMS</code>.</p></li><li><p>[ ] Add workflow structure and run the repository YAML linter; expect failure until matrix/release steps are complete.</p></li><li><p>[ ] Implement fixed runner labels, vcpkg cache, build, focused CTest, normalized asset names, checksums, and artifact uploads.</p></li><li><p>[ ] Publish with <code>contents: write</code> only for <code>v*</code> or explicit manual release input; create/update the tag&#39;s GitHub Release idempotently and fail on missing files.</p></li><li><p>[ ] Re-run YAML validation and inspect the event conditions; expect PASS.</p></li><li><p>[ ] Commit: <code>ci: build and release C++ installer</code>.</p></li></ul><h3 id="task-10-real-migration-and-e-tmp-portability-verification" tabindex="-1">Task 10: Real migration and E:\\tmp portability verification <a class="header-anchor" href="#task-10-real-migration-and-e-tmp-portability-verification" aria-label="Permalink to “Task 10: Real migration and E:\\tmp portability verification”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/tests/manual/migrate_legacy_sample.ps1</code></li><li>Create: <code>deploy/installer/tests/manual/verify_portable_move.ps1</code></li><li>Modify: <code>deploy/installer/README.md</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Migration script copies <code>D:\\Amusement\\BAAS_NEW</code> to a unique test directory and never modifies the source.</p></li><li><p>Move script requires explicit <code>-ConfirmMove</code> and targets <code>E:\\tmp\\BAAS_NEW-portable</code>.</p></li><li><p>[ ] Write assertions for migrated dual-schema TOML, valid main/OCR Git HEADs, OCR executable/marker, root-local uv paths, and moved venv Python.</p></li><li><p>[ ] Run scripts in <code>-WhatIf</code>; expect no mutation and report legacy missing conditions.</p></li><li><p>[ ] Implement safe copy, installer execution with launch disabled, post-migration checks, explicit move, uv path queries, dependency import, BAAS smoke launch, and old-path scan.</p></li><li><p>[ ] Run the real migration on the copy, then move the verified copy to <code>E:\\tmp</code>; expect all checks PASS after the old copied path is absent.</p></li><li><p>[ ] Commit: <code>test(installer): verify legacy portable migration</code>.</p></li></ul><h2 id="final-verification" tabindex="-1">Final verification <a class="header-anchor" href="#final-verification" aria-label="Permalink to “Final verification”">​</a></h2><ul><li>Run all CTest installer tests and the focused Python OCR marker test.</li><li>Build the Windows Release executable locally.</li><li>Validate workflow YAML and asset names.</li><li>Audit each design requirement against code, tests, workflow, and migration output.</li><li>Confirm the original <code>D:\\Amusement\\BAAS_NEW</code> was not modified.</li></ul><h3 id="task-11-full-session-tui-and-local-recovery-verification" tabindex="-1">Task 11: Full-session TUI and local recovery verification <a class="header-anchor" href="#task-11-full-session-tui-and-local-recovery-verification" aria-label="Permalink to “Task 11: Full-session TUI and local recovery verification”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/CMakeLists.txt</code></li><li>Modify: <code>deploy/installer/include/baas_installer/tui.hpp</code></li><li>Modify: <code>deploy/installer/src/tui.cpp</code></li><li>Modify: <code>deploy/installer/src/main.cpp</code></li><li>Modify: <code>deploy/installer/include/baas_installer/process.hpp</code></li><li>Modify: <code>deploy/installer/src/process.cpp</code></li><li>Modify: <code>deploy/installer/src/git.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_tui.cpp</code></li><li>Create: <code>deploy/installer/tests/test_process.cpp</code></li><li>Create: <code>deploy/installer/tests/manual/verify_local_migration.ps1</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>InstallerViewModel</code> owns setup, running, success, and failure screens plus thread-safe task rows.</p></li><li><p><code>run_tui(paths, install)</code> keeps one FTXUI event loop alive for the complete installer session.</p></li><li><p><code>run_process(spec)</code> captures child stdout/stderr into <code>&lt;root&gt;/log/installer.log</code> instead of inheriting the terminal.</p></li><li><p>Windows startup enables UTF-8 input/output and virtual-terminal processing before FTXUI starts.</p></li><li><p>[x] Add failing model tests for initial setup, parallel main/OCR progress, ordered deployment, uv progress, and terminal success/failure states.</p></li><li><p>[x] Run the focused TUI test and verify it fails because the full-session view model API is absent.</p></li><li><p>[x] Add a failing process test proving child output is captured and cannot reach the parent TUI stream.</p></li><li><p>[x] Run the focused process test and verify the inherited-output implementation fails it.</p></li><li><p>[x] Link FTXUI and implement one full-screen event loop with an in-TUI MirrorChyan form, task rows, aggregate progress, current detail, bounded log pane, retry, and exit controls.</p></li><li><p>[x] Run installation work on a worker thread and post progress events back to FTXUI; represent unknown byte totals with a spinner and known totals with a determinate bar.</p></li><li><p>[x] Configure Windows UTF-8/VT mode and compile source as UTF-8; keep Git, curl, tar, and uv output out of the console and append decoded diagnostic text to the root-local log.</p></li><li><p>[x] Re-run focused tests and the full CTest suite; expect PASS with no direct progress printing remaining.</p></li><li><p>[x] Build the Windows Release executable and copy <code>D:\\Amusement\\BAAS_NEW</code> to a fresh local D-drive test directory without changing the source.</p></li><li><p>[x] Run the new installer against that fresh copy and assert exit code zero, main deployment, OCR placement, uv/Python locality, dependency sync, valid <code>setup.toml</code>, valid marker, and no paths outside the copied root.</p></li><li><p>[x] Commit: <code>fix(installer): deliver full TUI and verified local install</code>.</p></li></ul>',65)]))}const h=t(o,[["render",r]]);export{m as __pageData,h as default};
